def sum_squares(n):
    squares = [x**2 for x in range(1, n+1)]
    return sum(squares)

def square_sum(n):
    nums = [x for x in range(1, n+1)]
    return sum(nums)**2

def sum_square_difference(n):
    x = square_sum(n)
    y = sum_squares(n)
    return x - y

